package com.alsafa.native4.core;import android.database.Cursor;/** Read-only local inventory summary for home UI. */public final class InventorySummaryStore{private final CoreStore.DbProvider p;public InventorySummaryStore(CoreStore.DbProvider p){this.p=p;}public java.util.List<LowStockItem> lowStock(int threshold,int limit){if(threshold<0||limit<1||limit>500)throw new IllegalArgumentException("Invalid inventory filter");java.util.ArrayList<LowStockItem> rows=new java.util.ArrayList<>();try(Cursor c=p.db().rawQuery("SELECT name,quantity FROM products WHERE deleted_at IS NULL AND quantity<=? ORDER BY quantity ASC,name ASC LIMIT ?",new String[]{String.valueOf(threshold),String.valueOf(limit)})){while(c.moveToNext())rows.add(new LowStockItem(c.getString(0),c.getInt(1)));}return java.util.Collections.unmodifiableList(rows);}public static final class LowStockItem{public final String name;public final int quantity;LowStockItem(String n,int q){name=n;quantity=q;}}public Summary read(){try(Cursor c=p.db().rawQuery("SELECT COUNT(*),COALESCE(SUM(CASE WHEN quantity<=1 THEN 1 ELSE 0 END),0),COALESCE(SUM(quantity),0) FROM products WHERE deleted_at IS NULL",null)){if(c.moveToFirst())return new Summary(c.getInt(0),c.getInt(1),c.getInt(2));return new Summary(0,0,0);}}public static final class Summary{public final int products,lowStock,units;Summary(int p,int l,int u){products=p;lowStock=l;units=u;}}}